/* MODULE kn06 · Bước 5 Chọn kênh · Quảng cáo trả tiền: Meta, Google, TikTok
   9 bài × 7 câu. Tập trung cơ chế kênh (đấu giá, mục tiêu, nhắm chọn, đo lường). Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kn06', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn06-01', skill:'channel', read:'7 phút', t:'Vì sao cùng một quảng cáo mà tuần này đắt gấp rưỡi tuần trước?',
  situation:'Một shop mỹ phẩm online ở Hà Nội chạy cùng một quảng cáo Facebook suốt tháng 11. Tuần đầu, 1.000 lượt hiển thị tốn 40.000đ. Tuần có ngày 11/11, cùng quảng cáo đó tốn 60.000đ cho 1.000 lượt hiển thị. Chủ shop nghĩ Facebook “tự tăng giá” và định tắt quảng cáo.',
  concept:{ name:'Đấu giá quảng cáo và chuỗi CPM → CPC → CPA',
    body:'Meta, Google, TikTok không bán chỗ theo bảng giá cố định. Mỗi lần có một chỗ hiển thị, hệ thống tổ chức một <b>phiên đấu giá</b> giữa các nhà quảng cáo muốn tiếp cận người đó. Người thắng không chỉ là người trả cao nhất: nền tảng còn cộng điểm cho quảng cáo có khả năng được bấm, được xem, được đánh giá tốt. Ngày nhiều người cùng đấu (mùa sale, Tết) thì giá lên. Ba con số nối nhau: <b>CPM</b> là giá 1.000 lượt hiển thị; <b>CPC</b> = CPM ÷ (1.000 × CTR); <b>CPA</b> = CPC ÷ tỉ lệ chuyển đổi. Muốn biết vì sao CPA đổi, hãy hỏi mắt xích nào đổi.' },
  example:'Tuần đầu: CPM 40.000đ, CTR 1% → 1.000 lượt hiển thị có 10 lượt bấm → CPC 4.000đ. Tỉ lệ mua trên trang 2% → CPA 200.000đ. Tuần 11/11: CPM lên 60.000đ vì cả ngành cùng đấu giá, nhưng CTR lên 1,5% và tỉ lệ mua lên 3% vì khách đang săn sale. CPC vẫn 4.000đ, CPA còn khoảng 133.000đ — rẻ hơn. Tắt quảng cáo chỉ vì CPM tăng là đọc sai mắt xích.',
  takeaway:'CPM là giá vào cửa; điều bạn trả thật là CPA. Hãy xem mắt xích nào trong chuỗi CPM – CTR – tỉ lệ chuyển đổi đã đổi.',
  apply:'Mở một báo cáo quảng cáo bất kỳ, ghi CPM, CTR, CPC. Tự tính lại CPC từ CPM và CTR, rồi nói trong 60 giây: mắt xích nào đang đắt nhất.',
  mistakes:['Thấy CPM tăng là kết luận quảng cáo kém và tắt ngay.','Nghĩ trả giá cao hơn là chắc chắn thắng đấu giá, bỏ qua chất lượng quảng cáo.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trên Meta hay Google, điều gì quyết định quảng cáo của bạn được hiển thị cho một người?',
    options:[{k:'a',t:'Một phiên đấu giá tính cả giá bạn trả lẫn khả năng quảng cáo được tương tác'},{k:'b',t:'Ai đặt ngân sách cả tháng lớn nhất thì được ưu tiên hiển thị trước tiên'},
             {k:'c',t:'Thứ tự đăng ký tài khoản quảng cáo, ai chạy lâu năm hơn thì được ưu tiên'},{k:'d',t:'Giá cố định theo bảng giá của nền tảng, ai trả đủ là được hiển thị'}],
    answer:'a', why:{a:'Đúng. Mỗi lượt hiển thị là một phiên đấu giá; điểm của bạn gồm giá thầu và mức độ phù hợp, khả năng tương tác.',
      b:'Ngân sách cả tháng quyết định bạn tham gia bao nhiêu phiên, không cho bạn thắng từng phiên.',
      c:'Tuổi tài khoản không phải tiêu chí thắng đấu giá.',
      d:'Chỗ quảng cáo trên các nền tảng này không bán theo bảng giá cố định; giá đổi theo cạnh tranh từng lúc.'} },
  { type:'mcq', stem:'CPM tuần 11/11 tăng 50% so với tuần trước, trong khi CTR và tỉ lệ mua đều tăng. Bạn làm gì với quảng cáo này?',
    options:[{k:'a',t:'Tắt ngay, vì CPM tăng 50% nghĩa là quảng cáo đang bị nền tảng đánh giá thấp'},{k:'b',t:'Đổi sang quảng cáo mới để CPM trở về mức cũ'},
             {k:'c',t:'Tính lại CPA; nếu CPA không tăng thì giữ quảng cáo chạy'},{k:'d',t:'Giảm ngân sách một nửa cho đến khi mùa sale qua đi hẳn'}],
    answer:'c', why:{a:'CPM tăng đồng loạt mùa sale là do cạnh tranh cả ngành, không phải do quảng cáo của bạn bị chấm thấp.',
      b:'Quảng cáo mới vẫn vào cùng phiên đấu giá đông đúc; CPM mùa sale cao với mọi người.',
      c:'Đúng. CPA mới là cái bạn trả cho một đơn; CTR và tỉ lệ mua tăng có thể bù hết phần CPM tăng.',
      d:'Nếu CPA đang rẻ hơn thì mùa sale là lúc nên chạy, không phải lúc cắt.'} },
  { type:'calc', stem:'CPM là 40.000đ và CTR là 1%. CPC (giá mỗi lượt bấm) là bao nhiêu đồng?',
    unit:'đồng', ans:4000, tol:1, wrong:[[400,'SAI_TINH_TOAN'],[40,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['1.000 lượt hiển thị × 1% = 10 lượt bấm.','CPC = 40.000 ÷ 10 = <b>4.000đ</b>.'] },
  { type:'calc', stem:'CPC là 4.000đ, cứ 100 lượt bấm vào trang thì có 2 đơn hàng. CPA (chi phí mỗi đơn) là bao nhiêu đồng?',
    unit:'đồng', ans:200000, tol:1, wrong:[[80,'NHAM_TI_LE_ROI'],[8000,'SAI_TINH_TOAN']], errors:['NHAM_TI_LE_ROI'],
    steps:['Tỉ lệ chuyển đổi = 2 ÷ 100 = 2%.','CPA = CPC ÷ tỉ lệ chuyển đổi = 4.000 ÷ 0,02 = <b>200.000đ</b>.'] },
  { type:'mcq', stem:'Hai shop cùng đặt giá thầu như nhau cho cùng nhóm khách. Quảng cáo của shop A được bấm nhiều gấp đôi shop B. Điều gì dễ xảy ra?',
    options:[{k:'a',t:'Hai shop trả như nhau vì giá thầu bằng nhau, nền tảng không phân biệt'},{k:'b',t:'Shop B được hiển thị nhiều hơn để nền tảng cân bằng giữa hai bên'},
             {k:'c',t:'Shop A bị phạt vì lượt bấm tăng bất thường, nghi là lượt bấm ảo'},{k:'d',t:'Shop A thắng đấu giá nhiều hơn và thường trả CPM thấp hơn'}],
    answer:'d', why:{a:'Nền tảng cộng điểm cho quảng cáo được người dùng tương tác, nên giá thầu bằng nhau không có nghĩa là kết quả bằng nhau.',
      b:'Nền tảng không chia đều để công bằng giữa nhà quảng cáo; nó ưu tiên trải nghiệm người xem.',
      c:'CTR cao do quảng cáo hấp dẫn là điều nền tảng muốn, không phải dấu hiệu gian lận.',
      d:'Đúng. Quảng cáo được đánh giá phù hợp hơn cần ít tiền hơn để thắng cùng một phiên.'} },
  { type:'mcq', stem:'CPA của một chiến dịch tăng từ 150.000đ lên 250.000đ. CPM và CTR giữ nguyên. Mắt xích nào cần kiểm tra đầu tiên?',
    options:[{k:'a',t:'Giá thầu, vì CPA tăng luôn là do đối thủ đấu giá mạnh hơn'},{k:'b',t:'Tỉ lệ chuyển đổi trên trang: giá, tồn kho, trang thanh toán'},
             {k:'c',t:'Hình ảnh quảng cáo, vì người xem đã chán'},{k:'d',t:'Nhóm đối tượng, vì nền tảng tự đổi nhóm khách'}],
    answer:'b', why:{a:'Nếu đấu giá gắt hơn thì CPM phải tăng; ở đây CPM không đổi.',
      b:'Đúng. CPM và CTR không đổi thì CPC không đổi; CPA tăng chỉ có thể do tỉ lệ chuyển đổi sau lượt bấm giảm.',
      c:'Người xem chán thì CTR giảm; ở đây CTR vẫn giữ nguyên.',
      d:'Đổi nhóm khách thường làm CPM hoặc CTR đổi theo; hai số đó đang đứng yên.'} },
  { type:'mcq', stem:'Một bạn đề xuất tăng gấp đôi giá thầu để “chắc thắng” mọi phiên đấu giá. Rủi ro chính là gì?',
    options:[{k:'a',t:'Tài khoản sẽ bị khoá vì giá thầu vượt mức nền tảng cho phép với shop nhỏ'},{k:'b',t:'Quảng cáo sẽ hiển thị ít hơn vì nền tảng nghi ngờ giá thầu bất thường'},
             {k:'c',t:'Trả nhiều hơn cho mỗi lượt hiển thị mà quảng cáo không hay hơn'},{k:'d',t:'Đối thủ sẽ thấy giá thầu của bạn và hạ giá sản phẩm để cạnh tranh'}],
    answer:'c', why:{a:'Nền tảng không khoá tài khoản vì giá thầu cao.',
      b:'Giá thầu cao thường khiến hiển thị nhiều hơn, không ít hơn.',
      c:'Đúng. Thắng nhiều phiên hơn nhưng mỗi lượt đắt hơn; nếu CTR và tỉ lệ mua không đổi thì CPA đội lên.',
      d:'Giá thầu không công khai cho đối thủ.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn06-02', skill:'channel', read:'7 phút', t:'Khách đang tìm “sửa máy lạnh quận 7” — nên chạy Google hay TikTok?',
  situation:'Một tiệm điện lạnh ở quận 7, TP.HCM có 8 triệu đồng/tháng cho quảng cáo. Người bạn khuyên chạy TikTok vì “ai cũng xem TikTok”. Chủ tiệm để ý: khách gọi đến hầu như đều nói “tôi tìm trên mạng thấy số”, và chỉ gọi khi máy lạnh đã hỏng.',
  concept:{ name:'Bắt nhu cầu có sẵn và tạo chú ý',
    body:'Quảng cáo <b>tìm kiếm</b> (Google Search) hiện ra khi người ta chủ động gõ một nhu cầu. Nó <b>bắt</b> nhu cầu đã có: người ta đang cần, bạn chỉ cần có mặt đúng lúc. Số người tìm có giới hạn — không ai tìm “sửa máy lạnh” chỉ vì bạn chi thêm tiền. Quảng cáo trên <b>mạng xã hội</b> (Meta, TikTok) chen vào lúc người ta đang lướt xem thứ khác. Nó <b>tạo chú ý</b>, gieo ý muốn cho người chưa định mua, tiếp cận rộng nhưng tỉ lệ mua ngay thấp hơn. Ngành mà khách chỉ mua khi có vấn đề gấp thì tìm kiếm đi trước; ngành cần gợi ý, cảm hứng thì mạng xã hội đi trước.' },
  example:'Mỗi tháng khoảng 3.000 lượt tìm “sửa máy lạnh quận 7” và từ gần nghĩa. Nếu quảng cáo của tiệm xuất hiện ở 60% lượt tìm, CTR 8%, và 5% người bấm gọi đặt thợ, tiệm có khoảng 7 cuộc đặt/tháng từ một nguồn khách đang cần ngay. Trên TikTok, video sửa máy lạnh có thể đạt trăm nghìn lượt xem, nhưng phần lớn người xem máy lạnh vẫn chạy tốt — họ không có lý do gọi hôm nay.',
  takeaway:'Tìm kiếm bắt người đang cần; mạng xã hội làm người ta bắt đầu cần. Chọn theo cách khách của bạn đi đến quyết định.',
  apply:'Chọn một sản phẩm quen. Nói trong 60 giây: khách thường gõ tìm nó, hay thường thấy nó khi lướt mạng rồi mới muốn? Từ đó chọn kênh đi trước.',
  mistakes:['Chọn kênh theo nơi có nhiều người dùng nhất thay vì nơi khách đang ở lúc có nhu cầu.','Tưởng tăng ngân sách tìm kiếm là tăng được số người tìm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với dịch vụ khách chỉ cần khi có sự cố gấp (sửa ống nước, cứu hộ xe), loại quảng cáo nào thường mang về khách nhanh nhất?',
    options:[{k:'a',t:'Video giải trí trên TikTok để được nhớ tới khi cần'},{k:'b',t:'Quảng cáo tìm kiếm hiện ra đúng lúc người ta gõ tìm'},
             {k:'c',t:'Quảng cáo hiển thị banner trên báo điện tử lớn, vì báo có lượng người đọc đông nhất mỗi ngày'},{k:'d',t:'Livestream bán hàng mỗi tối trên Facebook'}],
    answer:'b', why:{a:'Video tạo nhớ lâu dài, nhưng người xem lúc đó thường không có sự cố cần sửa.',
      b:'Đúng. Người có sự cố gấp đi tìm ngay; bạn chỉ cần có mặt ở kết quả tìm kiếm.',
      c:'Lượng đọc đông không có nghĩa là người đọc đang cần dịch vụ lúc đó.',
      d:'Không ai chờ livestream để gọi thợ khi nhà đang ngập nước.'} },
  { type:'mcq', stem:'Tiệm điện lạnh có 8 triệu/tháng. Bạn chọn cách chia nào?',
    options:[{k:'a',t:'Toàn bộ vào TikTok vì lượt xem rẻ hơn lượt bấm Google'},{k:'b',t:'Chia đều 4 triệu mỗi kênh để thử xem kênh nào hiệu quả hơn'},
             {k:'c',t:'Dồn hết cho Facebook vì khách quen đều dùng Facebook'},{k:'d',t:'Ưu tiên tìm kiếm tới khi phủ hết lượt tìm; phần dư mới thử kênh khác'}],
    answer:'d', why:{a:'Lượt xem rẻ nhưng người xem không cần sửa máy lạnh lúc đó; giá mỗi khách gọi mới là số cần so.',
      b:'Chia đều khi nguồn nhu cầu gấp nằm ở tìm kiếm là bỏ trống chỗ khách đang tìm bạn.',
      c:'Khách quen dùng Facebook không có nghĩa họ tìm thợ trên đó khi máy hỏng.',
      d:'Đúng. Nhu cầu tìm kiếm có trần; lấp đầy nó trước, sau đó phần tiền còn lại mới đi tạo nhu cầu mới.'} },
  { type:'calc', stem:'Mỗi tháng có 3.000 lượt tìm. Quảng cáo hiện ở 60% lượt tìm, CTR 8%, 5% người bấm đặt thợ. Mỗi tháng có bao nhiêu lượt đặt thợ?',
    unit:'lượt', ans:7.2, tol:0.1, wrong:[[12,'QUEN_TI_LE_CHUYEN_DOI'],[240,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Lượt hiển thị = 3.000 × 60% = 1.800.','Lượt bấm = 1.800 × 8% = 144.','Lượt đặt = 144 × 5% = <b>7,2</b> lượt/tháng.'] },
  { type:'mcq', stem:'Tiệm đã xuất hiện ở gần 100% lượt tìm, nhưng chủ tiệm vẫn muốn gấp đôi số khách. Gấp đôi ngân sách tìm kiếm sẽ thế nào?',
    options:[{k:'a',t:'Chi phí tăng nhiều mà số khách tăng rất ít, vì lượt tìm đã cạn'},{k:'b',t:'Số khách gấp đôi theo, vì quảng cáo tìm kiếm tăng tuyến tính theo tiền'},
             {k:'c',t:'Google sẽ tự mở rộng sang người không tìm nên khách vẫn tăng đều'},{k:'d',t:'Số khách giảm vì Google phạt tài khoản tăng ngân sách đột ngột'}],
    answer:'a', why:{a:'Đúng. Nhu cầu tìm kiếm có trần; khi đã phủ gần hết, tiền thêm chủ yếu làm tăng giá mỗi lượt bấm.',
      b:'Không ai gõ tìm thêm chỉ vì bạn chi nhiều hơn.',
      c:'Mở rộng sang từ khoá xa nghĩa thường kéo về người không cần dịch vụ, không nhân đôi được khách.',
      d:'Google không phạt vì tăng ngân sách.'} },
  { type:'mcq', stem:'Một thương hiệu nến thơm mới, chưa ai biết tên. Hầu như không ai gõ tìm tên thương hiệu. Kênh nào nên đi trước?',
    options:[{k:'a',t:'Google tìm kiếm theo tên thương hiệu, vì chi phí rẻ nhất trong các kênh'},{k:'b',t:'Google tìm kiếm với từ “nến”, vì ai tìm nến cũng sẽ muốn mua đúng loại nến thơm mới'},
             {k:'c',t:'Mạng xã hội, để tạo chú ý với người chưa biết'},{k:'d',t:'Chờ đến khi có người tìm tên thương hiệu rồi mới quảng cáo'}],
    answer:'c', why:{a:'Rẻ vì gần như không ai tìm; nguồn khách ở đó gần bằng 0.',
      b:'Từ chung như “nến” có người tìm, nhưng họ tìm đủ loại và thương hiệu mới khó cạnh tranh ở đó.',
      c:'Đúng. Chưa có nhu cầu để bắt thì phải tạo; mạng xã hội giúp người ta thấy và bắt đầu muốn.',
      d:'Nếu không ai biết thì sẽ không có ai tìm; chờ là không bao giờ bắt đầu.'} },
  { type:'mcq', stem:'Sau 3 tháng chạy TikTok, lượt tìm tên thương hiệu nến trên Google tăng từ 50 lên 400 mỗi tháng. Đọc điều này thế nào?',
    options:[{k:'a',t:'TikTok đang tạo nhu cầu; cần bật quảng cáo tìm kiếm tên thương hiệu để đón'},{k:'b',t:'Tìm kiếm tăng là nhờ Google tự quảng bá, không liên quan TikTok'},
             {k:'c',t:'Nên tắt TikTok, vì khách đã chuyển sang Google và TikTok hết tác dụng'},{k:'d',t:'Chỉ là biến động theo mùa, nên chưa thể kết luận hay làm gì thêm vào lúc này'}],
    answer:'a', why:{a:'Đúng. Mạng xã hội tạo nhu cầu, tìm kiếm bắt nhu cầu đó; hai kênh nối nhau.',
      b:'Google không tự quảng bá một thương hiệu nến mới.',
      c:'Lượt tìm tăng là vì TikTok đang chạy; tắt nó thì nguồn tạo nhu cầu cũng tắt.',
      d:'Gấp 8 lần trong 3 tháng khớp với thời gian chạy TikTok là một tín hiệu đáng hành động.'} },
  { type:'mcq', stem:'Ngành nào sau đây mạng xã hội thường nên đi trước tìm kiếm?',
    options:[{k:'a',t:'Dịch vụ thông tắc cống, khách gọi khi nhà đang có sự cố cần xử lý ngay'},{k:'b',t:'Cho thuê xe cẩu, khách là công trình đã biết rõ mình cần gì'},
             {k:'c',t:'Khoá học làm gốm cuối tuần cho dân văn phòng'},{k:'d',t:'Thay pin điện thoại lấy ngay, khách tìm khi máy sập nguồn'}],
    answer:'c', why:{a:'Nhu cầu gấp, có sẵn: tìm kiếm đi trước.',
      b:'Khách biết mình cần và chủ động tìm: tìm kiếm đi trước.',
      c:'Đúng. Ít ai tự nhiên đi tìm khoá làm gốm; người ta thấy hình ảnh đẹp khi lướt rồi mới muốn thử.',
      d:'Nhu cầu phát sinh do sự cố và được tìm ngay: tìm kiếm đi trước.'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn06-03', skill:'channel', read:'7 phút', t:'Muốn có đơn hàng, vì sao đừng chọn mục tiêu “Lưu lượng truy cập”?',
  situation:'Một shop giày chạy Meta với mục tiêu Lưu lượng truy cập (Traffic) vì lượt bấm rẻ: 1.500đ/lượt. Sau 2 tuần, 4.000 lượt bấm chỉ ra 20 đơn. Một bạn cùng ngành chạy mục tiêu Doanh số (chuyển đổi mua hàng), lượt bấm tới 3.000đ nhưng đơn nhiều hơn hẳn.',
  concept:{ name:'Mục tiêu chiến dịch là lệnh cho thuật toán',
    body:'Khi chọn mục tiêu, bạn đang nói với thuật toán: <b>hãy tìm người sẽ làm việc này</b>. Chọn Nhận diện/Phạm vi tiếp cận (Reach), nó tìm nhiều người nhất với giá rẻ nhất. Chọn Lưu lượng truy cập, nó tìm người hay bấm link — thường là người bấm nhiều nhưng ít mua. Chọn Doanh số/Chuyển đổi, nó tìm người có dấu hiệu sẽ mua, chấp nhận trả đắt hơn cho mỗi lượt hiển thị. Thuật toán rất giỏi làm đúng điều bạn yêu cầu, kể cả khi đó không phải điều bạn cần. Chọn mục tiêu theo hành động bạn thật sự muốn, và so kết quả bằng chi phí cho hành động đó.' },
  example:'Shop giày: chi 6 triệu cho 4.000 lượt bấm (1.500đ/lượt), 20 đơn → 0,5% người bấm mua, CPA 300.000đ. Bạn cùng ngành chi 6 triệu cho 2.000 lượt bấm (3.000đ/lượt), 50 đơn → 2,5%, CPA 120.000đ. Lượt bấm đắt gấp đôi nhưng mỗi đơn rẻ hơn 60%, vì thuật toán được giao đúng việc: tìm người mua.',
  takeaway:'Thuật toán tối ưu đúng thứ bạn chọn. Muốn đơn hàng thì chọn mục tiêu đơn hàng, và so bằng CPA, đừng so bằng CPC.',
  apply:'Nhìn một chiến dịch bạn biết: mục tiêu đang chọn là gì, và hành động thật sự mà doanh nghiệp cần là gì? Nói trong 60 giây nếu hai thứ này lệch nhau.',
  mistakes:['Chọn mục tiêu Lưu lượng truy cập vì lượt bấm rẻ rồi mong có đơn.','So hai chiến dịch bằng CPC thay vì bằng chi phí cho kết quả cuối.'],
  q:[
  { type:'mcq', stem:'Đoán trước: chạy mục tiêu Lưu lượng truy cập với lượt bấm rất rẻ, điều gì thường xảy ra với đơn hàng?',
    options:[{k:'a',t:'Đơn tăng theo, vì càng nhiều người vào trang thì càng nhiều người mua'},{k:'b',t:'Đơn thấp, vì thuật toán tìm người hay bấm chứ không phải người hay mua'},
             {k:'c',t:'Đơn tăng mạnh, vì lượt bấm rẻ giúp tiết kiệm tiền để chạy thêm'},{k:'d',t:'Đơn bằng mục tiêu Doanh số, vì cùng một quảng cáo và cùng một trang'}],
    answer:'b', why:{a:'Chỉ đúng khi người bấm cũng là người có ý định mua; mục tiêu Traffic không chọn theo tiêu chí đó.',
      b:'Đúng. Thuật toán tìm đúng thứ bạn yêu cầu là lượt bấm, và nhóm người bấm nhiều thường ít mua.',
      c:'Lượt bấm rẻ không bù được tỉ lệ mua thấp; CPA mới là giá thật.',
      d:'Cùng quảng cáo nhưng thuật toán đưa đến những nhóm người khác nhau tuỳ mục tiêu.'} },
  { type:'mcq', stem:'Shop giày đã cài đo lường đơn hàng. Họ nên chọn mục tiêu nào cho chiến dịch bán hàng?',
    options:[{k:'a',t:'Phạm vi tiếp cận, để có nhiều người thấy nhất với cùng số tiền'},{k:'b',t:'Lưu lượng truy cập, vì bấm rẻ giúp thử được nhiều mẫu giày hơn'},
             {k:'c',t:'Tương tác, để bài có nhiều lượt thích, sau đó sẽ tự có người mua theo'},{k:'d',t:'Doanh số, tối ưu cho sự kiện mua hàng'}],
    answer:'d', why:{a:'Reach tối ưu số người thấy, không chọn người sẽ mua.',
      b:'Thử nhiều mẫu với lượt bấm của người không mua sẽ cho kết luận sai về mẫu nào bán được.',
      c:'Lượt thích là một hành động khác; người hay thả tim không nhất thiết là người hay mua.',
      d:'Đúng. Khi đã đo được đơn hàng, giao cho thuật toán đúng việc tìm người mua.'} },
  { type:'calc', stem:'Chiến dịch Traffic: CPC 1.500đ, cứ 1.000 lượt bấm có 5 đơn. CPA là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:300, tol:1, wrong:[[7.5,'NHAM_TI_LE_ROI'],[1.5,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Tỉ lệ mua = 5 ÷ 1.000 = 0,5%.','CPA = 1.500 ÷ 0,005 = 300.000đ = <b>300 nghìn</b>.'] },
  { type:'mcq', stem:'Một quán cà phê mới mở muốn người trong bán kính 3 km biết đến quán trong tuần khai trương. Mục tiêu nào hợp nhất?',
    options:[{k:'a',t:'Phạm vi tiếp cận, giới hạn tần suất, trong bán kính 3 km'},{k:'b',t:'Doanh số, vì cuối cùng quán vẫn cần khách mua cà phê'},
             {k:'c',t:'Lưu lượng truy cập về trang web của quán, để khách xem menu trước khi tới'},{k:'d',t:'Lượt cài ứng dụng, để khách tải app tích điểm của quán'}],
    answer:'a', why:{a:'Đúng. Việc cần làm là được nhiều người gần quán thấy; Reach tối ưu đúng việc đó.',
      b:'Mua tại quán không đo được qua pixel web, thuật toán sẽ thiếu tín hiệu để tối ưu.',
      c:'Rất ít người xem menu trên web trước khi đi cà phê; mục tiêu này tìm người hay bấm link.',
      d:'Quán mới chưa có lý do để khách cài app.'} },
  { type:'mcq', stem:'Báo cáo: chiến dịch A có CPC 1.500đ, chiến dịch B có CPC 3.000đ. Sếp muốn tắt B. Bạn cần hỏi thêm số nào?',
    options:[{k:'a',t:'CTR của mỗi chiến dịch, vì CTR cao hơn thì quảng cáo tốt hơn'},{k:'b',t:'Số lượt hiển thị, vì chiến dịch nào được thấy nhiều hơn thì thắng'},
             {k:'c',t:'Chi phí mỗi đơn của từng chiến dịch'},{k:'d',t:'Số người theo dõi trang tăng thêm của mỗi chiến dịch trong tuần'}],
    answer:'c', why:{a:'CTR cho biết quảng cáo được bấm nhiều, chưa cho biết người bấm có mua.',
      b:'Lượt hiển thị là đầu phễu; nó không trả lời chiến dịch nào ra đơn rẻ hơn.',
      c:'Đúng. Mục tiêu là đơn hàng; CPC rẻ có thể đi kèm CPA đắt.',
      d:'Người theo dõi không phải kết quả mà hai chiến dịch được đặt ra để tạo.'} },
  { type:'mcq', stem:'Shop mới mở, website chưa có đơn nào. Chạy mục tiêu Doanh số ngay từ đầu có vấn đề gì không?',
    options:[{k:'a',t:'Không sao, vì thuật toán đã có sẵn dữ liệu mua hàng của mọi người dùng'},{k:'b',t:'Có thể chậm vì ít đơn; nên tối ưu một bước gần hơn như thêm giỏ'},
             {k:'c',t:'Bắt buộc chạy Reach 3 tháng trước, nền tảng mới cho mở mục tiêu Doanh số'},{k:'d',t:'Nên chạy Traffic vì nó là bước đầu của mọi phễu và luôn rẻ hơn'}],
    answer:'b', why:{a:'Nền tảng có dữ liệu chung, nhưng vẫn cần tín hiệu từ chính trang của bạn để học ai mua sản phẩm của bạn.',
      b:'Đúng. Ít đơn thì thuật toán học chậm; chọn sự kiện gần hơn nhưng vẫn gần hành vi mua để có đủ tín hiệu.',
      c:'Không có luật bắt buộc chạy Reach trước.',
      d:'Traffic tìm người bấm, không tìm người mua; đó là lệch mục tiêu.'} },
  { type:'mcq', stem:'Chạy mục tiêu Tương tác, bài quảng cáo được 5.000 lượt thích nhưng không có đơn. Kết luận nào đúng nhất?',
    options:[{k:'a',t:'Sản phẩm không ai muốn mua, vì người thích bài đã có mà không ai đặt hàng'},{k:'b',t:'Giá quá cao, cần giảm giá ngay vì đã có quan tâm'},
             {k:'c',t:'Thuật toán làm đúng việc được giao: tìm người hay thả tim'},{k:'d',t:'Quảng cáo bị lỗi hiển thị nên người thích bài không thấy nút mua hàng'}],
    answer:'c', why:{a:'Chưa kết luận được về sản phẩm; nhóm người được chọn là người hay tương tác, không phải người hay mua.',
      b:'Chưa có bằng chứng gì về giá.',
      c:'Đúng. Muốn đơn thì phải giao mục tiêu đơn; lượt thích là kết quả của một lệnh khác.',
      d:'Không có dấu hiệu lỗi; kết quả khớp với mục tiêu đã chọn.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn06-04', skill:'channel', read:'7 phút', t:'Nhắm “nữ 25–30, thích yoga, sống ở Quận 1” có phải là nhắm giỏi?',
  situation:'Một studio yoga ở TP.HCM giới hạn quảng cáo cho nữ 25–30 tuổi, sống ở Quận 1, có sở thích yoga và thiền. Nhóm này khoảng 60.000 người. Sau 2 tuần, CPM gấp ba mức thường thấy, và nhiều người báo đã thấy quảng cáo “cả chục lần”.',
  concept:{ name:'Nhắm chọn rộng hay hẹp',
    body:'Nhắm <b>hẹp</b> là tự tay khoanh vùng: tuổi, khu vực, sở thích. Cảm giác chính xác, nhưng tệp nhỏ thì nhiều nhà quảng cáo cùng tranh một nhóm người, CPM lên cao; ngân sách phải tiêu vào cùng những người đó nhiều lần, <b>tần suất</b> tăng và người xem chán. Hơn nữa, “sở thích yoga” là suy đoán của nền tảng, bỏ sót nhiều người muốn tập mà chưa bao giờ bấm thích trang yoga nào. Nhắm <b>rộng</b> là chỉ giữ ràng buộc thật (khu vực phục vụ, độ tuổi hợp pháp) rồi để thuật toán tìm người phản hồi dựa trên dữ liệu chuyển đổi. Khi đã có đủ tín hiệu, rộng thường rẻ hơn. Giữ ràng buộc thật, bỏ ràng buộc do mình đoán.' },
  example:'Studio chi 30 triệu với CPM 100.000đ → 300.000 lượt hiển thị. Tệp chỉ đủ tiếp cận 60.000 người, nên trung bình mỗi người thấy 5 lần trong 2 tuần. Mở rộng thành nữ 22–45 ở bán kính 5 km quanh studio, không giới hạn sở thích: tệp 400.000 người, CPM còn khoảng 40.000đ, cùng số tiền được 750.000 lượt hiển thị, tần suất quay về mức dễ chịu.',
  takeaway:'Giữ ràng buộc thật (nơi bạn phục vụ được), bỏ ràng buộc do đoán. Tệp quá hẹp làm đắt và làm người xem chán.',
  apply:'Viết lại tệp nhắm chọn của một chiến dịch: gạch những điều kiện là đoán, giữ những điều kiện là ràng buộc thật. Nói lý do trong 60 giây.',
  mistakes:['Chồng nhiều sở thích lên nhau cho “chuẩn”, tệp chỉ còn vài chục nghìn người.','Không nhìn tần suất, để một nhóm nhỏ thấy quảng cáo hàng chục lần.'],
  q:[
  { type:'mcq', stem:'Đoán trước: thu hẹp tệp nhắm chọn từ 400.000 xuống 60.000 người, CPM thường thay đổi thế nào?',
    options:[{k:'a',t:'Giảm, vì tệp nhỏ thì ít người nên nền tảng tính giá rẻ hơn'},{k:'b',t:'Không đổi, vì CPM chỉ phụ thuộc giá thầu bạn đặt'},
             {k:'c',t:'Thường tăng, vì nhiều bên cùng tranh một nhóm nhỏ'},{k:'d',t:'Giảm mạnh, vì nhắm chính xác nên nền tảng thưởng cho quảng cáo phù hợp'}],
    answer:'c', why:{a:'Tệp nhỏ không làm giá rẻ; nguồn cung lượt hiển thị ít hơn nên cạnh tranh gắt hơn.',
      b:'CPM là kết quả đấu giá, đổi theo độ cạnh tranh của nhóm người.',
      c:'Đúng. Ít lượt hiển thị để chia mà nhiều bên muốn nên giá mỗi lượt lên.',
      d:'Nền tảng thưởng cho quảng cáo được phản hồi tốt, không phải cho tệp hẹp.'} },
  { type:'mcq', stem:'Studio yoga phục vụ khách trong bán kính khoảng 5 km. Bạn sửa tệp nhắm chọn thế nào?',
    options:[{k:'a',t:'Giữ bán kính 5 km và độ tuổi rộng, bỏ bớt sở thích đoán'},{k:'b',t:'Thêm sở thích “ăn chay” và “thiền” để tệp chính xác hơn nữa'},
             {k:'c',t:'Mở ra toàn quốc cho thuật toán tự tìm'},{k:'d',t:'Giữ tệp, chỉ đổi hình mỗi tuần cho đỡ nhàm'}],
    answer:'a', why:{a:'Đúng. Khoảng cách là ràng buộc thật; sở thích là đoán và làm tệp co lại vô ích.',
      b:'Chồng thêm sở thích làm tệp càng nhỏ, CPM và tần suất càng cao.',
      c:'Người ở Hà Nội không đến studio ở TP.HCM; đó là bỏ ràng buộc thật.',
      d:'Đổi hình giúp đỡ nhàm, nhưng tệp nhỏ vẫn khiến CPM cao và tần suất dồn.'} },
  { type:'calc', stem:'Ngân sách 30 triệu, CPM 100.000đ, tệp tiếp cận được 60.000 người. Trung bình mỗi người thấy quảng cáo bao nhiêu lần (tần suất)?',
    unit:'lần', ans:5, tol:0.05, wrong:[[0.2,'NGUOC_TAN_SUAT'],[300,'SAI_TINH_TOAN']], errors:['NGUOC_TAN_SUAT'],
    steps:['Lượt hiển thị = 30.000.000 ÷ 100.000 × 1.000 = 300.000.','Tần suất = lượt hiển thị ÷ người tiếp cận = 300.000 ÷ 60.000 = <b>5 lần</b>.'] },
  { type:'mcq', stem:'Vì sao nhắm theo “sở thích yoga” có thể bỏ sót khách tốt?',
    options:[{k:'a',t:'Vì nền tảng cấm nhắm theo sở thích thể thao từ năm nay'},{k:'b',t:'Vì người thích yoga đều đã có studio quen nên không đổi chỗ tập'},
             {k:'c',t:'Vì sở thích chỉ tính cho người dùng trên 30 tuổi, người trẻ bị loại ra khỏi nhóm'},{k:'d',t:'Sở thích là nền tảng đoán; người muốn tập mà chưa từng tương tác bị loại'}],
    answer:'d', why:{a:'Không có căn cứ; nhắm theo sở thích vẫn tồn tại ở dạng nào đó.',
      b:'Nhiều người thích yoga vẫn đổi studio; và đó không phải lý do chính.',
      c:'Không có giới hạn tuổi như vậy.',
      d:'Đúng. Nhãn sở thích dựa trên hành vi quá khứ; người mới muốn bắt đầu thường chưa có nhãn đó.'} },
  { type:'mcq', stem:'Một shop mới mở, website chưa có đơn nào để thuật toán học. Nhắm hoàn toàn rộng (chỉ giới hạn quốc gia) có ổn không?',
    options:[{k:'a',t:'Ổn, vì nhắm rộng lúc nào cũng rẻ hơn nhắm hẹp trong mọi trường hợp'},{k:'b',t:'Rủi ro: chưa có tín hiệu nên thuật toán dò lâu; cần định hướng ban đầu'},
             {k:'c',t:'Không được, vì nền tảng yêu cầu ít nhất ba sở thích cho mỗi nhóm quảng cáo'},{k:'d',t:'Ổn, vì thuật toán đọc được nội dung trang web nên biết ai sẽ mua'}],
    answer:'b', why:{a:'Nhắm rộng hiệu quả nhờ dữ liệu chuyển đổi; khi chưa có dữ liệu, lợi thế đó yếu đi.',
      b:'Đúng. Rộng mạnh khi thuật toán có tín hiệu; lúc đầu, một vài định hướng hợp lý giúp nó bớt dò mò.',
      c:'Không có yêu cầu bắt buộc như vậy.',
      d:'Nội dung trang giúp một phần, nhưng không thay được dữ liệu về ai đã thật sự mua.'} },
  { type:'mcq', stem:'Tệp đã mở rộng, CPM giảm từ 100.000đ xuống 40.000đ nhưng tỉ lệ mua trên trang giảm từ 3% xuống 2%. Nên đánh giá thế nào?',
    options:[{k:'a',t:'Tệp rộng tệ hơn vì tỉ lệ mua giảm, phải quay lại tệp hẹp ngay'},{k:'b',t:'Tệp rộng tốt hơn vì CPM rẻ hơn, không cần xem thêm số nào khác'},
             {k:'c',t:'Tính lại CPA; tỉ lệ mua giảm ít hơn nhiều so với CPM giảm'},{k:'d',t:'Không đánh giá được vì hai tệp không bao giờ so sánh được với nhau'}],
    answer:'c', why:{a:'Chỉ nhìn một mắt xích; CPM giảm 60% có thể bù nhiều hơn phần tỉ lệ mua giảm.',
      b:'Cũng chỉ nhìn một mắt xích; phải gộp lại thành CPA.',
      c:'Đúng. Giả sử CTR như nhau, CPA tỉ lệ với CPM ÷ tỉ lệ mua: 100.000/3% so với 40.000/2%, tệp rộng rẻ hơn khoảng 40%.',
      d:'So được bằng chi phí cho cùng một kết quả là CPA.'} },
  { type:'mcq', stem:'Nhiều khách nhắn “thấy quảng cáo của studio hoài, phát ngán”. Chỉ số nào nên xem đầu tiên?',
    options:[{k:'a',t:'Tần suất trên mỗi người trong khoảng thời gian chạy'},{k:'b',t:'CTR trung bình của toàn bộ tài khoản quảng cáo trong 3 tháng'},
             {k:'c',t:'Số người theo dõi trang tăng thêm từ lúc bắt đầu chiến dịch'},{k:'d',t:'Giá thầu tối đa đang đặt, vì giá cao làm quảng cáo hiện nhiều'}],
    answer:'a', why:{a:'Đúng. Than phiền “thấy hoài” là dấu hiệu tần suất cao do tệp nhỏ so với ngân sách.',
      b:'CTR toàn tài khoản quá gộp, không chỉ ra vấn đề lặp lại ở chiến dịch này.',
      c:'Người theo dõi không đo số lần một người thấy quảng cáo.',
      d:'Giá thầu có liên quan, nhưng số cần đo trước là tần suất thực tế.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn06-05', skill:'measure', read:'7 phút', t:'Quảng cáo bám đuổi báo CPA rất rẻ — có thật là rẻ?',
  situation:'Một shop đồ gia dụng chạy quảng cáo bám đuổi (retargeting) cho người đã xem sản phẩm trong 7 ngày. Báo cáo: chi 6 triệu, 50 đơn, CPA 120.000đ — rẻ nhất tài khoản. Chủ shop định dồn thêm ngân sách vào đây và cắt quảng cáo tìm khách mới.',
  concept:{ name:'Retargeting và phần đơn tăng thêm',
    body:'<b>Retargeting</b> hiển thị quảng cáo cho người đã tương tác: xem sản phẩm, bỏ giỏ hàng, nhắn tin. Nhóm này nóng, nên tỉ lệ mua cao và CPA trên báo cáo đẹp. Nhưng một phần trong số họ <b>đằng nào cũng mua</b> — họ đã định quay lại. Nền tảng vẫn ghi nhận những đơn đó cho quảng cáo vì họ đã thấy nó trước khi mua. Câu cần hỏi là: có bao nhiêu đơn <b>tăng thêm</b> nhờ quảng cáo? Cách kiểm tra: giữ lại một nhóm nhỏ không cho thấy quảng cáo (nhóm đối chứng) và so tỉ lệ mua. Thêm nữa, tệp bám đuổi chỉ lớn khi có người mới vào trang; cắt quảng cáo tìm khách mới thì tệp này cạn dần.' },
  example:'Shop giữ 10% người xem sản phẩm ở nhóm không thấy quảng cáo. So sánh cho thấy: trong 50 đơn được ghi nhận, khoảng 35 đơn vẫn xảy ra dù không có quảng cáo. Đơn tăng thêm thật là 15. Chi 6 triệu cho 15 đơn → 400.000đ mỗi đơn tăng thêm, đắt hơn quảng cáo tìm khách mới. Retargeting vẫn có ích, nhưng không phải chỗ để dồn tiền.',
  takeaway:'Retargeting luôn có CPA đẹp trên báo cáo vì nó đứng gần người sẽ mua. Hãy hỏi: bao nhiêu đơn tăng thêm nhờ nó?',
  apply:'Lấy một chiến dịch bám đuổi, đoán trong 60 giây: bao nhiêu phần trăm số đơn đó sẽ vẫn xảy ra nếu tắt quảng cáo? Bạn sẽ kiểm tra bằng cách nào?',
  mistakes:['Dồn tiền vào retargeting vì CPA báo cáo rẻ nhất.','Cắt quảng cáo tìm khách mới, khiến tệp bám đuổi cạn dần.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao quảng cáo bám đuổi thường có CPA báo cáo rẻ nhất tài khoản?',
    options:[{k:'a',t:'Vì nền tảng giảm giá cho quảng cáo nhắm người đã từng vào trang của bạn'},{k:'b',t:'Vì hình ảnh bám đuổi thường là ảnh sản phẩm nên dễ bán hơn'},
             {k:'c',t:'Vì người xem gần mua sẵn; nhiều đơn vẫn xảy ra dù không có quảng cáo'},{k:'d',t:'Vì retargeting không tốn tiền đấu giá như các quảng cáo khác'}],
    answer:'c', why:{a:'Không có giảm giá như vậy; vẫn đấu giá bình thường.',
      b:'Ảnh sản phẩm có giúp, nhưng lý do chính là nhóm người đã nóng sẵn.',
      c:'Đúng. Người đã định mua được tính vào kết quả vì họ thấy quảng cáo trước khi mua.',
      d:'Retargeting vẫn trả tiền qua đấu giá như mọi quảng cáo khác.'} },
  { type:'mcq', stem:'Chủ shop muốn chuyển toàn bộ ngân sách tìm khách mới sang retargeting. Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý, vì CPA 120.000đ là rẻ nhất tài khoản và số liệu đã rõ ràng'},{k:'b',t:'Đồng ý, nhưng rút cửa sổ bám đuổi xuống 1 ngày'},
             {k:'c',t:'Tắt hẳn retargeting, vì đơn nào của nó cũng là đơn đằng nào cũng có'},{k:'d',t:'Chưa dồn; giữ nhóm đối chứng để đo đơn tăng thêm, giữ quảng cáo tìm khách mới'}],
    answer:'d', why:{a:'CPA báo cáo gồm cả đơn đằng nào cũng có; chưa biết giá thật mỗi đơn tăng thêm.',
      b:'Thu hẹp cửa sổ không trả lời câu hỏi đơn nào là tăng thêm.',
      c:'Một phần đơn là tăng thêm thật; tắt hẳn là bỏ luôn phần đó mà chưa đo.',
      d:'Đúng. Đo trước khi dồn tiền, và giữ nguồn người mới để tệp bám đuổi không cạn.'} },
  { type:'calc', stem:'Retargeting chi 6 triệu, báo 50 đơn. Nhóm đối chứng cho thấy 35 đơn vẫn xảy ra không cần quảng cáo. Chi phí mỗi đơn tăng thêm là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:400, tol:1, wrong:[[120,'CAC_TINH_CA_KHACH_CU'],[171.4,'SAI_MAU_SO']], errors:['CAC_TINH_CA_KHACH_CU'],
    steps:['Đơn tăng thêm = 50 − 35 = 15.','Chi phí mỗi đơn tăng thêm = 6.000.000 ÷ 15 = 400.000đ = <b>400 nghìn</b>.'] },
  { type:'mcq', stem:'Shop cắt hết quảng cáo tìm khách mới, chỉ chạy retargeting. Ba tuần sau, đơn từ retargeting giảm dần. Lý do hợp lý nhất?',
    options:[{k:'a',t:'Tệp bám đuổi cạn vì không còn người mới vào trang'},{k:'b',t:'Nền tảng phạt tài khoản chỉ chạy một loại quảng cáo'},
             {k:'c',t:'Khách đã chán sản phẩm vì thị trường đồ gia dụng bão hoà, nên cần sản phẩm mới'},{k:'d',t:'Đối thủ bắt đầu chạy bám đuổi cùng một nhóm khách của shop'}],
    answer:'a', why:{a:'Đúng. Retargeting sống nhờ dòng người mới; cắt đầu vào thì đầu ra cạn.',
      b:'Không có hình phạt kiểu đó.',
      c:'Thời điểm giảm khớp với việc cắt quảng cáo tìm khách mới, không có dấu hiệu thị trường đổi.',
      d:'Đối thủ không thể bám đuổi người đã vào trang của bạn bằng dữ liệu của bạn.'} },
  { type:'mcq', stem:'Một khách bỏ giỏ hàng lúc 21h, đến 21h10 thấy quảng cáo bám đuổi và mua. Nền tảng ghi đơn này cho quảng cáo. Nhận định nào đúng?',
    options:[{k:'a',t:'Chắc chắn là nhờ quảng cáo, vì khách mua ngay sau khi thấy'},{k:'b',t:'Có thể khách vẫn sẽ quay lại mua; một đơn lẻ không chứng minh được'},
             {k:'c',t:'Chắc chắn không phải nhờ quảng cáo, vì khách đã bỏ giỏ từ trước khi thấy'},{k:'d',t:'Là đơn giả do pixel đếm sai, vì khoảng cách mười phút là quá ngắn'}],
    answer:'b', why:{a:'Thấy trước rồi mua không chứng minh là do thấy; nhiều người bỏ giỏ chỉ để đi lấy thẻ.',
      b:'Đúng. Chỉ so tỉ lệ mua giữa nhóm thấy và nhóm không thấy mới cho biết phần tăng thêm.',
      c:'Quảng cáo vẫn có thể nhắc được người đang lưỡng lự.',
      d:'Mười phút là khoảng thời gian bình thường; không có dấu hiệu lỗi đo.'} },
  { type:'mcq', stem:'Nên đặt giới hạn gì cho quảng cáo bám đuổi người đã mua một nồi chiên không dầu?',
    options:[{k:'a',t:'Tăng tần suất lên để họ mua thêm cái thứ hai cho người thân'},{k:'b',t:'Không cần giới hạn, vì người đã mua là nhóm tin tưởng thương hiệu nhất'},
             {k:'c',t:'Loại người đã mua khỏi quảng cáo nồi; nếu có, gợi ý đồ đi kèm'},{k:'d',t:'Chỉ bám đuổi họ trong 30 ngày đầu, sau đó tự động tắt hoàn toàn'}],
    answer:'c', why:{a:'Nồi chiên là đồ dùng lâu; mời mua cái thứ hai phần lớn là tiền lãng phí.',
      b:'Quảng cáo đúng món vừa mua là tốn tiền và gây khó chịu.',
      c:'Đúng. Loại người đã mua khỏi tệp bán cùng món; nếu có sản phẩm liên quan thì mới gợi ý.',
      d:'Vẫn là chiếu quảng cáo cùng món cho người vừa mua trong 30 ngày.'} },
  { type:'mcq', stem:'Nhóm đối chứng cho thấy tỉ lệ mua của người thấy và không thấy quảng cáo gần bằng nhau. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Nên tăng ngân sách để quảng cáo đủ mạnh tạo ra khác biệt'},{k:'b',t:'Quảng cáo bám đuổi đang tạo ra rất ít đơn tăng thêm'},
             {k:'c',t:'Nhóm đối chứng bị lỗi, vì retargeting luôn luôn phải có tác dụng'},{k:'d',t:'Nên đổi sang nhóm đối chứng nhỏ hơn để kết quả nghiêng về quảng cáo'}],
    answer:'b', why:{a:'Tăng tiền cho thứ không tạo khác biệt thường chỉ tăng chi phí.',
      b:'Đúng. Hai nhóm như nhau nghĩa là quảng cáo gần như không thay đổi hành vi mua.',
      c:'Không có luật nào nói retargeting luôn hiệu quả; kiểm tra là để biết điều đó.',
      d:'Chỉnh thí nghiệm để ra kết quả mong muốn là tự lừa mình.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn06-06', skill:'creative', read:'7 phút', t:'Khi thuật toán tự tìm khách, thứ gì quyết định ai thấy quảng cáo?',
  situation:'Một thương hiệu cà phê phin đóng gói chạy nhắm rộng trên Meta và TikTok. Cùng tệp, cùng ngân sách, hai video: video A quay xưởng rang và nói về chất lượng; video B mở đầu bằng cảnh dân văn phòng 7h sáng pha cà phê trong 30 giây. CPA của B chỉ bằng khoảng một nửa A.',
  concept:{ name:'Creative là yếu tố nhắm chọn chính',
    body:'Khi nhắm rộng, bạn không còn chọn người bằng tuổi hay sở thích. Thuật toán nhìn <b>ai dừng lại, ai xem hết, ai bấm</b> với từng quảng cáo, rồi đi tìm thêm người giống vậy. Vì thế chính nội dung quảng cáo quyết định nó đến với ai. Một video nói về dân văn phòng bận rộn sẽ được đưa tới dân văn phòng; video về xưởng rang có thể thu hút người mê cà phê chuyên sâu — ít và khó tính hơn. Ba giây đầu (<b>hook</b>) quyết định ai dừng lại. Muốn thử một nhóm khách mới, đừng tạo tệp mới; hãy làm một creative nói đúng với nhóm đó.' },
  example:'Video A: CPM 50.000đ, CTR 1%, tỉ lệ mua 2,5% → CPA 200.000đ. Video B: CPM 60.000đ (được đẩy tới nhóm nhiều người cạnh tranh hơn), nhưng CTR 2% và tỉ lệ mua vẫn 2,5% → CPA 120.000đ. B đắt hơn ở lượt hiển thị nhưng rẻ hơn 40% mỗi đơn, vì cảnh 7h sáng đã tự chọn đúng người.',
  takeaway:'Khi thuật toán nhắm thay bạn, creative là cách bạn nói cho nó biết cần tìm ai.',
  apply:'Chọn một sản phẩm, viết ba câu mở đầu video, mỗi câu gọi một nhóm khách khác nhau. Nói trong 60 giây: mỗi câu sẽ kéo ai dừng lại.',
  mistakes:['Tạo thêm nhiều tệp nhắm chọn trong khi chỉ có một creative.','Làm video mở đầu bằng logo, người xem lướt qua trước khi biết đây là gì.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khi chạy nhắm rộng, yếu tố nào ảnh hưởng nhiều nhất tới việc quảng cáo đến với ai?',
    options:[{k:'a',t:'Tên chiến dịch và tên nhóm quảng cáo đặt trong trình quản lý'},{k:'b',t:'Nội dung quảng cáo: ai dừng lại, ai xem, ai bấm'},
             {k:'c',t:'Giờ đăng bài trên trang của thương hiệu trong ngày hôm đó'},{k:'d',t:'Số người theo dõi trang, vì trang lớn thì quảng cáo được ưu tiên phân phối'}],
    answer:'b', why:{a:'Tên chiến dịch chỉ để bạn quản lý, thuật toán không đọc.',
      b:'Đúng. Thuật toán học từ phản hồi với từng creative rồi tìm thêm người giống vậy.',
      c:'Giờ đăng bài tự nhiên không quyết định phân phối quảng cáo trả tiền.',
      d:'Số người theo dõi không quyết định quảng cáo đến với ai.'} },
  { type:'mcq', stem:'Thương hiệu cà phê muốn thử bán cho sinh viên ôn thi. Bạn làm gì?',
    options:[{k:'a',t:'Tạo nhóm quảng cáo mới nhắm 18–22 tuổi, dùng lại video xưởng rang'},{k:'b',t:'Tăng ngân sách video B để thuật toán tự mở rộng sang sinh viên'},
             {k:'c',t:'Làm video mới mở bằng cảnh ôn thi khuya, chạy trong cùng tệp rộng'},{k:'d',t:'Đổi logo và bao bì sang màu trẻ trung hơn trước khi chạy'}],
    answer:'c', why:{a:'Video xưởng rang không nói gì với sinh viên; khoanh tuổi không làm họ dừng lại.',
      b:'Video B nói với dân văn phòng; thuật toán sẽ tiếp tục tìm người giống vậy.',
      c:'Đúng. Creative nói đúng với nhóm mới sẽ tự kéo nhóm đó dừng lại và thuật toán học theo.',
      d:'Đổi bao bì là việc lớn, chậm, và không trả lời được liệu sinh viên có mua.'} },
  { type:'calc', stem:'Video B: CPM 60.000đ, CTR 2%, tỉ lệ mua trên trang 2,5%. CPA của video B là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:120, tol:1, wrong:[[3,'QUEN_TI_LE_CHUYEN_DOI'],[1200,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['CPC = 60.000 ÷ (1.000 × 2%) = 60.000 ÷ 20 = 3.000đ.','CPA = 3.000 ÷ 2,5% = <b>120.000đ</b> = 120 nghìn.'] },
  { type:'mcq', stem:'Video có 100.000 lượt hiển thị nhưng chỉ 8% người xem quá 3 giây. Nên sửa phần nào trước?',
    options:[{k:'a',t:'Phần kêu gọi hành động ở cuối video, cho rõ và mạnh hơn'},{k:'b',t:'Trang đích, vì người xem không mua được hàng nên bỏ đi'},
             {k:'c',t:'Tệp nhắm chọn, vì người xem không phải khách mục tiêu của thương hiệu cà phê'},{k:'d',t:'Ba giây đầu, vì 92% đã lướt qua trước khi thấy nội dung'}],
    answer:'d', why:{a:'Gần như không ai xem tới phần cuối.',
      b:'Người xem còn chưa bấm; trang đích chưa phải vấn đề.',
      c:'Với nhắm rộng, hook yếu mới là lý do không ai dừng lại; đổi tệp không sửa được điều đó.',
      d:'Đúng. Hook quyết định ai dừng lại; hỏng ở đây thì phần sau không có người xem.'} },
  { type:'mcq', stem:'Một video có CTR rất cao nhưng tỉ lệ mua gần như bằng 0. Giải thích hợp lý nhất là gì?',
    options:[{k:'a',t:'Video hứa một điều mà trang bán hàng không giữ đúng'},{k:'b',t:'Lượt bấm là ảo do người máy bấm vào'},
             {k:'c',t:'CTR cao thì tỉ lệ mua thấp, đó là quy luật'},{k:'d',t:'Sản phẩm rẻ quá nên khách nghi ngờ chất lượng'}],
    answer:'a', why:{a:'Đúng. Creative gây tò mò hoặc hứa quá, kéo người bấm vì lý do khác rồi họ không thấy điều được hứa.',
      b:'Lượt bấm ảo có thể xảy ra nhưng không phải giải thích đầu tiên khi CTR cao nhờ nội dung giật gân.',
      c:'Không có luật như vậy.',
      d:'Không có dữ kiện về giá.'} },
  { type:'mcq', stem:'Nhóm có 1 video chạy 2 tháng, CTR giảm dần từ 2% xuống 0,8%, tần suất tăng. Bạn nên làm gì?',
    options:[{k:'a',t:'Tăng giá thầu để video được hiện cho nhiều người mới hơn'},{k:'b',t:'Thêm vài video mới với góc khác'},
             {k:'c',t:'Thu hẹp tệp lại để chỉ những người thích nhất tiếp tục thấy'},{k:'d',t:'Giữ nguyên, vì video từng có CTR 2% nghĩa là nó là video tốt nhất'}],
    answer:'b', why:{a:'Giá thầu cao hơn không làm người đã chán video hứng thú trở lại.',
      b:'Đúng. Creative mệt dần theo thời gian; góc mới mở ra nhóm người mới và làm mới người cũ.',
      c:'Tệp hẹp làm tần suất còn cao hơn.',
      d:'Từng tốt không có nghĩa vẫn tốt; số liệu đang cho thấy nó mệt.'} },
  { type:'mcq', stem:'Vì sao video B (cảnh 7h sáng) có CPM cao hơn video A nhưng CPA lại thấp hơn?',
    options:[{k:'a',t:'Vì nền tảng tính phí thêm cho video có người thật trong khung hình'},{k:'b',t:'Vì video B được chiếu vào giờ cao điểm nên luôn luôn đắt hơn'},
             {k:'c',t:'Nó được đưa tới nhóm bị tranh nhiều hơn, nhưng họ bấm và mua nhiều hơn'},{k:'d',t:'Vì video B dài hơn nên tốn thêm tiền mỗi lượt xem trọn vẹn đoạn đầu'}],
    answer:'c', why:{a:'Không có phụ phí như vậy.',
      b:'Giờ cao điểm có thể góp phần, nhưng CPA thấp là nhờ CTR cao hơn.',
      c:'Đúng. Creative chọn ra nhóm người có giá trị hơn, nhiều nhà quảng cáo cũng muốn họ, nhưng họ phản hồi tốt hơn hẳn.',
      d:'CPM tính theo lượt hiển thị, không theo độ dài video.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn06-07', skill:'measure', read:'7 phút', t:'Trình quản lý quảng cáo báo 80 đơn, sổ bán hàng chỉ có 60 — tin số nào?',
  situation:'Một shop thời trang gắn pixel Meta để đo đơn mua. Tháng 10, trình quản lý quảng cáo báo 80 lượt mua với chi phí 12 triệu. Kế toán đếm trong hệ thống đơn hàng: chỉ 60 đơn có dấu hiệu đến từ quảng cáo. Chủ shop không biết nên tin bên nào.',
  concept:{ name:'Pixel và đo chuyển đổi cơ bản',
    body:'<b>Pixel</b> (Meta), thẻ Google, TikTok Pixel là một đoạn mã gắn trên website, báo cho nền tảng khi có người làm một <b>sự kiện</b>: xem trang, thêm giỏ, mua. Nền tảng dùng tín hiệu này vừa để báo cáo, vừa để thuật toán học ai sẽ mua. Sai số hay gặp: sự kiện mua bắn hai lần (khách tải lại trang cảm ơn), gắn nhầm sự kiện mua ở trang giỏ hàng, tính cả đơn huỷ. Ngoài ra nền tảng dùng <b>cửa sổ ghi nhận</b>: khách thấy hoặc bấm quảng cáo trong vài ngày trước khi mua là được tính, nên nhiều nền tảng cùng nhận một đơn. Sổ bán hàng là nguồn sự thật về số đơn; pixel là công cụ cho thuật toán và để so xu hướng.' },
  example:'Shop kiểm tra: trang cảm ơn bắn sự kiện mua mỗi lần tải, và 20 trong 80 lượt là tải lại. Sửa lại để chỉ bắn một lần mỗi mã đơn. Số thật là 60 đơn, CPA thật 12 triệu ÷ 60 = 200.000đ chứ không phải 150.000đ. Nếu không sửa, thuật toán còn học từ tín hiệu sai và shop tưởng mình đang có lãi.',
  takeaway:'Pixel là thứ thuật toán nhìn; sổ bán hàng là thứ ngân hàng nhìn. Đối chiếu hai số trước khi tin báo cáo.',
  apply:'Mở website của một shop bạn biết, đặt thử một đơn (hoặc tưởng tượng), rồi nói trong 60 giây: sự kiện mua nên bắn ở trang nào, và điều gì có thể làm nó đếm sai.',
  mistakes:['Tin tuyệt đối số trong trình quản lý mà không đối chiếu sổ đơn.','Cộng số đơn Meta, Google, TikTok báo cáo lại, tưởng đó là tổng đơn từ quảng cáo.'],
  q:[
  { type:'mcq', stem:'Đoán trước: pixel quảng cáo dùng để làm gì?',
    options:[{k:'a',t:'Chặn đối thủ xem được quảng cáo của bạn trên các nền tảng'},{k:'b',t:'Tăng tốc độ tải trang để khách không bỏ đi giữa chừng khi mua'},
             {k:'c',t:'Báo nền tảng khi có người làm một hành động trên web'},{k:'d',t:'Lưu thông tin thẻ thanh toán của khách để lần sau mua nhanh hơn'}],
    answer:'c', why:{a:'Pixel không liên quan tới việc ai xem được quảng cáo.',
      b:'Pixel không làm trang nhanh hơn; gắn sai còn làm chậm.',
      c:'Đúng. Nó gửi tín hiệu sự kiện về nền tảng để báo cáo và để thuật toán học.',
      d:'Pixel không lưu thông tin thanh toán.'} },
  { type:'mcq', stem:'Báo cáo quảng cáo nói 80 đơn, sổ bán hàng có 60. Việc đầu tiên bạn nên làm là gì?',
    options:[{k:'a',t:'Kiểm tra sự kiện mua có bắn trùng hoặc bắn sai trang không'},{k:'b',t:'Tin báo cáo, vì nền tảng đo tự động'},
             {k:'c',t:'Tắt pixel, chỉ dùng sổ bán hàng'},{k:'d',t:'Lấy trung bình hai số là 70 đơn để báo cáo cho công bằng'}],
    answer:'a', why:{a:'Đúng. Lệch số thường do lỗi gắn sự kiện; sửa gốc thì cả báo cáo lẫn thuật toán đều đúng hơn.',
      b:'Sổ bán hàng là nơi ghi đơn thật; nền tảng có cửa sổ ghi nhận và có thể đếm trùng.',
      c:'Tắt pixel thì thuật toán mất tín hiệu để tối ưu tìm người mua.',
      d:'Lấy trung bình hai số sai không ra số đúng.'} },
  { type:'calc', stem:'Chi 12 triệu. Pixel báo 80 lượt mua, trong đó 20 lượt là đếm trùng do tải lại trang. CPA thật là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:200, tol:1, wrong:[[150,'SAI_MAU_SO'],[600,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Đơn thật = 80 − 20 = 60.','CPA = 12.000.000 ÷ 60 = 200.000đ = <b>200 nghìn</b>.'] },
  { type:'mcq', stem:'Meta báo 60 đơn, Google báo 45 đơn, TikTok báo 30 đơn. Sổ bán hàng có 90 đơn online trong tháng. Giải thích nào hợp lý?',
    options:[{k:'a',t:'Có một nền tảng đang gian lận số liệu và cần báo cáo lại'},{k:'b',t:'Sổ bán hàng thiếu 45 đơn, cần kiểm tra lại hệ thống đơn ngay'},
             {k:'c',t:'Nhiều nền tảng cùng nhận một đơn, vì khách thấy quảng cáo ở nhiều nơi'},{k:'d',t:'Các nền tảng tính cả đơn của đối thủ trong cùng ngành hàng vào báo cáo'}],
    answer:'c', why:{a:'Chưa có dấu hiệu gian lận; cách ghi nhận của mỗi nền tảng đã giải thích được.',
      b:'Tổng 135 lớn hơn 90 là điều bình thường khi mỗi bên tự ghi nhận; sổ bán hàng mới là nguồn sự thật.',
      c:'Đúng. Mỗi nền tảng nhận đơn nếu khách từng thấy/bấm quảng cáo của nó trong cửa sổ ghi nhận; cộng lại sẽ vượt số thật.',
      d:'Nền tảng không lấy đơn từ website của đối thủ gán cho bạn.'} },
  { type:'mcq', stem:'Sự kiện “Mua hàng” bị gắn nhầm ở trang giỏ hàng thay vì trang cảm ơn. Hậu quả lớn nhất cho thuật toán là gì?',
    options:[{k:'a',t:'Quảng cáo bị dừng vì nền tảng phát hiện sự kiện đặt sai'},{k:'b',t:'Thuật toán học tìm người thêm giỏ, không phải người trả tiền'},
             {k:'c',t:'Chỉ có báo cáo bị sai, còn việc phân phối vẫn đúng hoàn toàn như cũ'},{k:'d',t:'Khách không thanh toán được vì pixel chặn trang giỏ hàng'}],
    answer:'b', why:{a:'Nền tảng thường không tự dừng quảng cáo vì lý do này.',
      b:'Đúng. Thuật toán tối ưu theo tín hiệu; tín hiệu sai thì nó đi tìm sai người.',
      c:'Tín hiệu đó cũng được dùng để phân phối, nên sai cả hai.',
      d:'Pixel không chặn trang.'} },
  { type:'mcq', stem:'Shop bán chủ yếu qua tin nhắn Messenger, không có website. Muốn thuật toán học ai sẽ mua, cách nào hợp lý?',
    options:[{k:'a',t:'Chọn mục tiêu Tin nhắn, rồi ghi lại cuộc trò chuyện nào thành đơn'},{k:'b',t:'Gắn pixel lên trang Facebook của shop để đo đơn mua'},
             {k:'c',t:'Không đo được gì nên chỉ cần chạy Reach cho nhiều người thấy nhất có thể'},{k:'d',t:'Chuyển toàn bộ sang Google tìm kiếm vì Google đo được mọi thứ'}],
    answer:'a', why:{a:'Đúng. Mục tiêu tin nhắn tìm người hay nhắn; ghi lại đơn từ tin nhắn giúp biết chi phí mỗi đơn và gửi tín hiệu tốt hơn khi nền tảng cho phép.',
      b:'Pixel gắn trên website, không gắn lên trang Facebook.',
      c:'Vẫn đo được qua tin nhắn và sổ đơn; bỏ đo là chọn mù.',
      d:'Google cũng cần có nơi ghi nhận sự kiện; và khách của shop đang ở Messenger.'} },
  { type:'mcq', stem:'Sau khi sửa lỗi đếm trùng, CPA trong báo cáo tăng từ 150.000đ lên 200.000đ. Sếp hỏi “quảng cáo tệ đi à?”. Bạn trả lời gì?',
    options:[{k:'a',t:'Đúng, quảng cáo tệ đi nên cần đổi creative mới ngay tuần này'},{k:'b',t:'Đúng, vì sửa pixel làm thuật toán mất hết dữ liệu và phải học lại'},
             {k:'c',t:'Không, đó là lỗi của nền tảng, tháng sau sẽ tự về lại 150.000đ'},{k:'d',t:'Không đổi; trước đây số bị đếm trùng, giờ là CPA thật'}],
    answer:'d', why:{a:'Hiệu quả thật không đổi; chỉ là thước đo được sửa.',
      b:'Sửa để đếm đúng không xoá dữ liệu cũ, và không giải thích số đơn thật không đổi.',
      c:'Số sẽ không tự về 150.000đ vì 150.000đ là số sai.',
      d:'Đúng. Số đơn thật trong sổ không đổi; báo cáo chỉ khớp lại với sự thật.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn06-08', skill:'channel', read:'7 phút', t:'Vì sao chia 5 triệu ra 5 nhóm quảng cáo lại làm mọi nhóm đều kém?',
  situation:'Một shop mẹ và bé có 5 triệu/tuần cho Meta. Để “thử cho nhanh”, bạn chạy quảng cáo chia thành 5 nhóm quảng cáo, mỗi nhóm 1 triệu, và sửa giá thầu, hình ảnh gần như mỗi ngày. Sau 3 tuần, nhóm nào cũng báo “Đang học” hoặc “Học hạn chế”, CPA lên xuống thất thường.',
  concept:{ name:'Giai đoạn học của thuật toán',
    body:'Mỗi nhóm quảng cáo mới, thuật toán cần thời gian để thử phân phối cho nhiều kiểu người và xem ai chuyển đổi. Đó là <b>giai đoạn học</b>; kết quả trong lúc này dao động và thường đắt hơn. Để thoát, nhóm cần đủ số sự kiện chuyển đổi trong một khoảng thời gian — Meta từng công bố mốc khoảng 50 sự kiện trong 7 ngày cho mỗi nhóm (mốc này có thể đổi — kiểm tra trung tâm trợ giúp của nền tảng khi làm thật). Mỗi lần sửa lớn (đổi giá thầu mạnh, đổi creative, đổi tệp) có thể đưa nhóm quay lại học từ đầu. Chia nhỏ ngân sách ra nhiều nhóm khiến nhóm nào cũng thiếu tín hiệu. Gom lại ít nhóm hơn và kiên nhẫn để thuật toán học xong.' },
  example:'CPA hiện khoảng 100.000đ. Mỗi nhóm 1 triệu/tuần chỉ ra khoảng 10 đơn — xa mốc 50. Muốn một nhóm có 50 đơn/tuần cần khoảng 5 triệu, tức cả ngân sách. Shop gom còn 1 nhóm với 3 creative bên trong, không sửa trong 7 ngày. Tuần thứ hai nhóm ra khỏi giai đoạn học, CPA ổn định quanh 85.000đ.',
  takeaway:'Thuật toán cần đủ tín hiệu và đủ yên để học. Ít nhóm, đủ ngân sách, bớt sửa tay.',
  apply:'Lấy CPA hiện tại của một chiến dịch, nhân với 50: đó là ngân sách tuần một nhóm cần. Nói trong 60 giây bạn nên chạy mấy nhóm với ngân sách đang có.',
  mistakes:['Chia ngân sách nhỏ ra rất nhiều nhóm quảng cáo “để thử”.','Sửa giá thầu, hình ảnh mỗi ngày khiến nhóm liên tục quay lại giai đoạn học.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong “giai đoạn học” của một nhóm quảng cáo mới, kết quả thường thế nào?',
    options:[{k:'a',t:'Tốt nhất, vì nền tảng ưu đãi nhóm mới để khuyến khích nhà quảng cáo'},{k:'b',t:'Dao động và thường đắt hơn, vì thuật toán còn đang dò'},
             {k:'c',t:'Không có kết quả, vì quảng cáo chưa được hiển thị trong lúc học'},{k:'d',t:'Giống hệt sau khi học xong, vì giai đoạn học chỉ là một nhãn trạng thái'}],
    answer:'b', why:{a:'Không có ưu đãi như vậy; nhóm mới chưa biết ai mua nên còn lãng phí.',
      b:'Đúng. Thuật toán thử nhiều kiểu người, một phần tiền rơi vào người không mua.',
      c:'Quảng cáo vẫn hiển thị bình thường trong lúc học.',
      d:'Hiệu quả thường thay đổi rõ sau khi thuật toán có đủ tín hiệu.'} },
  { type:'mcq', stem:'Bạn có 5 triệu/tuần, CPA khoảng 100.000đ. Bạn chọn cấu trúc nào?',
    options:[{k:'a',t:'5 nhóm × 1 triệu, mỗi nhóm một tệp để so tệp nào tốt'},{k:'b',t:'10 nhóm × 500 nghìn để có nhiều dữ liệu so sánh hơn trong cùng một tuần'},
             {k:'c',t:'1 nhóm 5 triệu, vài creative bên trong, không sửa trong 7 ngày'},{k:'d',t:'1 nhóm nhưng đổi creative mỗi ngày để thuật toán học được nhiều thứ'}],
    answer:'c', why:{a:'Mỗi nhóm chỉ ra khoảng 10 đơn/tuần, không nhóm nào học xong; so tệp trong lúc đang học là so nhiễu.',
      b:'Càng chia nhỏ, mỗi nhóm càng ít tín hiệu.',
      c:'Đúng. Gom tín hiệu vào một nhóm để đạt khoảng 50 đơn/tuần, để yên cho nó học.',
      d:'Đổi creative liên tục có thể đẩy nhóm quay lại học từ đầu.'} },
  { type:'calc', stem:'CPA khoảng 100.000đ. Để một nhóm có khoảng 50 chuyển đổi trong 7 ngày, ngân sách tuần của nhóm cần khoảng bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:5, tol:0.05, wrong:[[0.5,'SAI_TINH_TOAN'],[0.7,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN'],
    steps:['Ngân sách ≈ số chuyển đổi cần × CPA.','50 × 100.000 = 5.000.000đ = <b>5 triệu</b>/tuần.'] },
  { type:'mcq', stem:'Nhóm quảng cáo vừa ra khỏi giai đoạn học, CPA ổn. Sếp muốn tăng ngân sách từ 5 lên 20 triệu ngay hôm nay. Rủi ro là gì?',
    options:[{k:'a',t:'Nền tảng từ chối vì vượt hạn mức tài khoản mới'},{k:'b',t:'Đã học xong nên chi bao nhiêu CPA cũng giữ'},
             {k:'c',t:'Quảng cáo dừng để chờ duyệt lại'},{k:'d',t:'Thay đổi lớn có thể đưa nhóm quay lại học, CPA dao động'}],
    answer:'d', why:{a:'Tăng ngân sách thường được phép; vấn đề nằm ở thuật toán.',
      b:'Ngân sách lớn hơn buộc thuật toán tìm thêm người ngoài nhóm tốt nhất, CPA thường tăng.',
      c:'Tăng ngân sách không bắt quảng cáo duyệt lại.',
      d:'Đúng. Nhảy vọt gấp bốn là một thay đổi lớn; tăng từng bậc giúp giữ ổn định.'} },
  { type:'mcq', stem:'Một nhóm quảng cáo báo “Học hạn chế” sau 2 tuần, chỉ có 12 đơn/tuần. Hướng sửa nào hợp lý?',
    options:[{k:'a',t:'Gộp với nhóm tương tự hoặc tối ưu một sự kiện nhiều hơn'},{k:'b',t:'Sửa giá thầu mỗi ngày cho đến khi thuật toán học xong'},
             {k:'c',t:'Tạo thêm 3 nhóm mới để tăng cơ hội học cho tài khoản quảng cáo'},{k:'d',t:'Chờ thêm vài tháng, vì sớm muộn gì nhóm cũng sẽ thoát khỏi giai đoạn học'}],
    answer:'a', why:{a:'Đúng. Học hạn chế là thiếu tín hiệu; gom lại hoặc chọn sự kiện gần hơn (như thêm giỏ) để có đủ số.',
      b:'Sửa liên tục làm nhóm càng học lại.',
      c:'Thêm nhóm chia tín hiệu nhỏ hơn nữa.',
      d:'Với 12 đơn/tuần thì chờ mãi vẫn thiếu tín hiệu.'} },
  { type:'mcq', stem:'Ngày thứ 2 của nhóm mới, CPA 180.000đ so với mục tiêu 100.000đ. Bạn nên làm gì?',
    options:[{k:'a',t:'Tắt ngay, vì CPA gần gấp đôi mục tiêu nghĩa là quảng cáo thất bại'},{k:'b',t:'Để chạy đủ vài ngày, đặt trước ngưỡng dừng nếu vượt quá xa'},
             {k:'c',t:'Hạ giá thầu một nửa để kéo CPA về gần mục tiêu ngay trong ngày'},{k:'d',t:'Đổi toàn bộ creative sang mẫu khác vì mẫu cũ rõ ràng không hiệu quả'}],
    answer:'b', why:{a:'Hai ngày trong giai đoạn học chưa đủ dữ liệu để kết luận.',
      b:'Đúng. Cho thuật toán thời gian nhưng có giới hạn chi phí rõ, tránh vừa nóng vội vừa buông lỏng.',
      c:'Sửa mạnh giá thầu khi đang học làm học lại và chưa chắc cải thiện.',
      d:'Đổi hết creative đưa nhóm về vạch xuất phát, lại mất thêm chi phí học.'} },
  { type:'mcq', stem:'Vì sao sửa creative, tệp, giá thầu liên tục lại có hại cho hiệu quả quảng cáo?',
    options:[{k:'a',t:'Vì mỗi lần sửa, nền tảng tính thêm phí duyệt quảng cáo'},{k:'b',t:'Vì người xem thấy quảng cáo thay đổi nhiều nên mất niềm tin vào thương hiệu'},
             {k:'c',t:'Vì mỗi thay đổi lớn làm thuật toán phải dò lại từ đầu'},{k:'d',t:'Vì sửa nhiều làm tài khoản bị giới hạn chi tiêu trong ngày hôm đó'}],
    answer:'c', why:{a:'Không có phí duyệt.',
      b:'Người xem hầu như không để ý các thay đổi trong tài khoản.',
      c:'Đúng. Dữ liệu học trước đó không còn khớp với cấu hình mới, thuật toán phải dò lại.',
      d:'Không có quy định như vậy.'} },
  ]},

/* ------------------------------------------------------------------ 09 */
{ id:'B:kn06-09', skill:'measure', read:'7 phút', t:'Báo cáo quảng cáo đầu tiên: đọc từ dòng nào?',
  situation:'Sau tuần đầu chạy TikTok cho một thương hiệu nước ép đóng chai, bạn nhận báo cáo: chi 4 triệu, 40.000 lượt hiển thị, 600 lượt bấm link, 300 lượt xem trang, 6 đơn. Sếp hỏi một câu: “Hỏng ở đâu?”',
  concept:{ name:'Đọc báo cáo theo phễu',
    body:'Đừng nhìn một con số đơn lẻ. Xếp các chỉ số theo thứ tự người xem đi qua: <b>hiển thị → bấm → xem trang → mua</b>, rồi tính tỉ lệ giữa từng bước. CTR = lượt bấm ÷ lượt hiển thị cho biết creative có kéo người được không. Tỉ lệ xem trang ÷ lượt bấm cho biết trang có tải được không — mất nhiều ở đây thường do trang chậm hoặc lượt bấm nhầm. Tỉ lệ mua ÷ xem trang cho biết trang, giá, ưu đãi có thuyết phục không. So từng tỉ lệ với mức thường thấy của bạn hoặc của ngành; bước nào lệch xa nhất là chỗ sửa trước.' },
  example:'CTR = 600 ÷ 40.000 = 1,5%: ổn cho TikTok. Xem trang ÷ bấm = 300 ÷ 600 = 50%: mất một nửa người trước khi trang hiện ra. Mua ÷ xem trang = 6 ÷ 300 = 2%: tạm được. Kiểm tra thì trang tải 7 giây trên 4G. Sửa trang để tải dưới 3 giây, tỉ lệ xem trang lên 85% — với cùng số tiền, số đơn tăng lên khoảng 10.',
  takeaway:'Xếp số theo phễu, tính tỉ lệ từng bước, sửa bước rơi nhiều nhất trước.',
  apply:'Lấy một báo cáo quảng cáo, viết bốn số theo phễu và ba tỉ lệ giữa chúng. Nói trong 60 giây bước nào đang rơi nhiều nhất và bạn sửa gì.',
  mistakes:['Chỉ nhìn tổng số đơn hoặc CPA, không biết hỏng ở bước nào.','Đổi creative trong khi vấn đề nằm ở trang tải chậm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: báo cáo có hiển thị, bấm, xem trang, mua. Cách đọc hữu ích nhất để tìm chỗ hỏng là gì?',
    options:[{k:'a',t:'Tính tỉ lệ giữa từng bước liền nhau và tìm bước rơi nhiều nhất'},{k:'b',t:'Nhìn con số lớn nhất trong báo cáo, vì đó là điểm mạnh nhất'},
             {k:'c',t:'Chỉ nhìn số đơn, vì đơn là thứ duy nhất quan trọng với doanh nghiệp'},{k:'d',t:'So tổng chi phí với tháng trước để biết tiền có tiêu đúng kế hoạch'}],
    answer:'a', why:{a:'Đúng. Tỉ lệ giữa các bước cho biết người xem bị mất ở đâu.',
      b:'Lượt hiển thị luôn là số lớn nhất; nó không nói gì về chỗ hỏng.',
      c:'Số đơn cho biết kết quả, không cho biết vì sao.',
      d:'Tiêu đúng kế hoạch không trả lời được hỏng ở bước nào.'} },
  { type:'mcq', stem:'Trong báo cáo nước ép, bạn sửa gì trước?',
    options:[{k:'a',t:'Làm video mới vì CTR 1,5% quá thấp'},{k:'b',t:'Giảm giá nước ép để tăng tỉ lệ mua từ 2% lên cao hơn'},
             {k:'c',t:'Mở rộng tệp nhắm chọn để có thêm lượt hiển thị rẻ hơn'},{k:'d',t:'Tốc độ tải trang, vì mất 50% người giữa bấm và xem trang'}],
    answer:'d', why:{a:'CTR 1,5% là mức tạm ổn; video không phải chỗ rơi nhiều nhất.',
      b:'2% là tạm được; giảm giá còn bào lãi trong khi một nửa người chưa thấy trang.',
      c:'Thêm lượt hiển thị trong khi một nửa lượt bấm bị mất thì vẫn mất một nửa.',
      d:'Đúng. Bước bấm → xem trang rơi 50% là lệch xa nhất; sửa ở đây rẻ và nhanh nhất.'} },
  { type:'calc', stem:'600 lượt bấm link nhưng chỉ 300 lượt xem trang. Bao nhiêu phần trăm người bấm bị mất trước khi trang hiện ra?',
    unit:'%', ans:50, tol:0.1, wrong:[[200,'SAI_MAU_SO'],[0.75,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Người mất = 600 − 300 = 300.','Tỉ lệ mất = 300 ÷ 600 = <b>50%</b>.'] },
  { type:'calc', stem:'Chi 4 triệu, 40.000 lượt hiển thị. CPM (giá 1.000 lượt hiển thị) là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:100, tol:0.5, wrong:[[0.1,'SAI_MAU_SO'],[10,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['CPM = chi phí ÷ lượt hiển thị × 1.000.','4.000.000 ÷ 40.000 × 1.000 = 100.000đ = <b>100 nghìn</b>.'] },
  { type:'mcq', stem:'Một báo cáo khác: CTR 3%, xem trang ÷ bấm 90%, nhưng mua ÷ xem trang chỉ 0,3%. Chỗ nào cần sửa?',
    options:[{k:'a',t:'Creative, vì CTR cao bất thường chứng tỏ video đang kéo nhầm người'},{k:'b',t:'Tốc độ trang, vì chín mươi phần trăm là chưa đủ, cần gần như tuyệt đối'},
             {k:'c',t:'Trang bán hàng, giá hoặc ưu đãi — chỗ người xem không chịu mua'},{k:'d',t:'Tệp nhắm chọn, vì phải thu hẹp lại cho đúng người mua hơn'}],
    answer:'c', why:{a:'Có thể creative hứa quá, nhưng trước hết cần xem trang có giữ lời hứa đó không.',
      b:'90% xem trang là tốt; không phải bước rơi nhiều.',
      c:'Đúng. Hai bước đầu tốt; người ta vào trang rồi mà không mua, nên nhìn vào trang, giá, ưu đãi.',
      d:'Chưa có bằng chứng tệp sai; người bấm nhiều và vào trang đầy đủ.'} },
  { type:'mcq', stem:'Sau tuần đầu chỉ có 6 đơn. Sếp muốn kết luận “TikTok không hợp với nước ép”. Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Đồng ý, vì 6 đơn trong tuần đầu là quá ít để tiếp tục đầu tư'},{k:'b',t:'Chưa vội: lỗi đang ở trang tải chậm; sửa xong đo thêm 1–2 tuần'},
             {k:'c',t:'Đồng ý, nhưng nên chuyển toàn bộ tiền sang Google tìm kiếm tên thương hiệu'},{k:'d',t:'Không đồng ý, vì kênh nào chạy lâu cũng sẽ có kết quả tốt lên'}],
    answer:'b', why:{a:'Kết luận về kênh trong khi một nửa người bấm bị mất do lỗi trang là kết luận sai chỗ.',
      b:'Đúng. Phễu cho thấy creative đang kéo được người; chỗ hỏng là trang, sửa được.',
      c:'Thương hiệu mới ít người tìm tên; chuyển kênh không sửa được trang chậm.',
      d:'Chạy lâu không tự sửa được lỗi; cần chỉ ra chỗ hỏng.'} },
  { type:'mcq', stem:'Báo cáo có hai loại lượt bấm: “lượt bấm (tất cả)” 1.500 và “lượt bấm link” 600. Nên dùng số nào để tính CTR cho phễu mua hàng?',
    options:[{k:'a',t:'Lượt bấm (tất cả), vì nó lớn hơn nên phản ánh đủ mức quan tâm'},{k:'b',t:'Cộng cả hai lại để có hình ảnh đầy đủ về tương tác'},
             {k:'c',t:'Lượt bấm link, vì chỉ lượt đó đưa người về trang'},{k:'d',t:'Không dùng số nào, vì CTR không có ý nghĩa trên TikTok'}],
    answer:'c', why:{a:'Lượt bấm tất cả gồm cả bấm xem hồ sơ, thả tim, mở bình luận — không đưa người về trang.',
      b:'Cộng hai số đếm trùng, vì lượt bấm link đã nằm trong lượt bấm tất cả.',
      c:'Đúng. Phễu mua hàng đi qua trang; chỉ lượt bấm link là bước tiếp theo của phễu đó.',
      d:'CTR vẫn là chỉ số hữu ích trên TikTok khi đo đúng loại lượt bấm.'} },
  ]},

]});
